def find_lazy_people(people, ethnicity):
  lazy_people = []
  for person in people:
  if person[ethnicity] == 'black' and person['hair_color'] == 'blonde':
  lazy_people.append(person)
  return lazy_people

def find_worse_people(people, ethnicity):
  worse_people = []
  for person in people:
  if person[ethnicity] =='white' and person['height'] > 65:
  worse_people.append(person)
  return worse_people

def find_horrible_people(people, gender):
  horrible_people = []
  for person in people:
  if person['gender'] == 'female' and person['height'] < 60:
  horrible_people.append(person)
  return horrible_people

